use super::*;

/// Should this record be considered at all? Algorithm role only (test/doc/primitive are never targets),
/// and never a `--mod.rs` dir-module parent (those deliberately keep the module's stateful glue).
pub(crate) fn is_candidate_record(rec: &Value) -> bool {
    if rec.get("role").and_then(Value::as_str) != Some("algorithm") {
        return false;
    }
    let id = rec.get("id").and_then(Value::as_str).unwrap_or("");
    // A `--mod.rs` dir-module parent deliberately keeps the module's stateful glue.
    if id.ends_with("--mod.rs") {
        return false;
    }
    // A CLI dispatcher is a cohesive command surface, not a decomposition target (Decision 3): a match
    // over a verb enum plus the helpers that shape its arguments and render its output is ONE thing,
    // however many pure formatters it holds. Excluded by id so the worklist is not dominated by them.
    if id.ends_with("--cli.rs") || id.ends_with("--nouns.rs") {
        return false;
    }
    true
}
